MetalHeapAllocator::~MetalHeapAllocator() {
	for (uint32_t p = 0; p < POOL_COUNT; p++) {
		Pool &pool = pools[p];
		for (Block &block : pool.blocks) {
			if (block.metadata != nullptr) {
				memdelete(block.metadata);
			}
		}
		for (MTL::Heap *heap : pool.dedicated_heaps) {
			heap->release();
		}
	}
}
